var b = buffer_create(16, buffer_fixed, 1);
var n = steam_remote_storage_file_read("gametest_no_such_file.bin", b);
buffer_delete(b);
show_debug_message("gametest: file_read of a missing file: " + string(n) + ", " + string(steam_api_last_error()));
return (n == 0 && string_pos("doesn't exist", steam_api_last_error()) > 0) ? 1 : 0;
